-- Check all column names across all tables for PCI-related terms
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name ILIKE '%pci%' OR column_name ILIKE '%cred%' OR column_name ILIKE '%score%';

BEGIN;
ALTER TABLE account ADD COLUMN review_priority TEXT DEFAULT NULL;
UPDATE account SET review_priority = 'Flagged for Review'
WHERE accindex IN (
    SELECT a.accindex
    FROM account a
    JOIN profile p ON a.accindex = p.profaccref
    JOIN sessionbehavior sb ON p.profkey = sb.sessprofref
    JOIN networkmetrics nm ON sb.sessref = nm.netsessref
    JOIN technicalinfo ti ON nm.netkey = ti.technetref
    JOIN securitydetection sd ON ti.techkey = sd.sectechref
    GROUP BY a.accindex
    HAVING MAX(ti.iprepscore) > 0.8
       AND (MAX(sd.detecttime) IS NULL OR CURRENT_DATE - MAX(sd.detecttime)::date > 180)
);
COMMIT;

DO $$ 
BEGIN 
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'account' AND column_name = 'review_priority') THEN
        EXECUTE 'ALTER TABLE account ADD COLUMN review_priority TEXT';
    END IF;
END $$;
UPDATE account SET review_priority = 'Flagged for Review' WHERE accindex IN (SELECT DISTINCT a.accindex FROM account a JOIN profile p ON a.accindex = p.profaccref JOIN sessionbehavior sb ON p.profkey = sb.sessprofref JOIN networkmetrics nm ON sb.sessref = nm.netsessref JOIN technicalinfo ti ON nm.netkey = ti.technetref JOIN securitydetection sd ON ti.techkey = sd.sectechref WHERE ti.iprepscore > 0.8 AND (sd.detecttime IS NULL OR CURRENT_DATE - sd.detecttime::date > 180));
